import asyncio

async def upload_report(send, notify):
    for attempt in range(3):
        try:
            await asyncio.wait_for(send(), timeout=10)
            return True
        except (TimeoutError, ConnectionError):
            if attempt < 2:
                await asyncio.sleep(2 ** attempt)
    notify("Upload failed; report remains available locally")
    return False
